import { Link } from '@tanstack/react-router';
import { ClientRow } from '../../slots/defs/clientRow';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClientSearch } from './ClientSearch';
import { useClients } from './clients';

// The clients list. Reads server data straight from its query key — never copied into state, never
// handed down from a parent. The name filter lives in the URL (`clientSearch`), read directly here;
// the search box owns that same key, so the two stay in step without any import between them.
// Archived clients are tucked away: they drop off the list and search but are retained server-side.
export function ClientList() {
  const { data: clients } = useClients();
  const [query] = useSearchParam('clientSearch', asString);

  if (!clients) {
    return null;
  }

  if (clients.length === 0) {
    return (
      <>
        <ClientSearch />
        <p data-testid="clients-empty">No clients yet.</p>
      </>
    );
  }

  const active = clients.filter((client) => !client.archived);
  const needle = query.trim().toLowerCase();
  const visible = needle
    ? active.filter((client) => client.name.toLowerCase().includes(needle))
    : active;

  return (
    <>
      <ClientSearch />
      <table data-testid="clients-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {visible.map((client) => (
          <tr key={client.id} data-testid={`client-row-${client.id}`}>
            <td data-testid="client-name">{client.name}</td>
            <td data-testid="client-email">{client.email}</td>
            <td>
              <Link
                to="/clients/$clientId"
                params={{ clientId: String(client.id) }}
                data-testid={`client-open-${client.id}`}
              >
                Open
              </Link>
            </td>
            <td>
              <ClientRow.Slot client={client} />
            </td>
          </tr>
        ))}
        </tbody>
      </table>
    </>
  );
}
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// The shape the server returns and the query key everything that shows clients shares. Two features
// stay in step by invalidating ['clients']; nothing imports a sibling to refresh it.
export type Client = { id: number; name: string; email: string; archived: boolean };

export const clientsKey = ['clients'] as const;

export function useClients() {
  return useQuery({
    queryKey: clientsKey,
    queryFn: () => getJson<Client[]>('/api/clients'),
  });
}

export function useCreateClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { name: string; email: string }) =>
      postJson<Client>('/api/clients', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}

// Archive a client instead of deleting it: POSTs {id} and returns the id archived. The client is
// kept server-side with its archived flag set; invalidating ['clients'] re-reads every view so the
// row drops off the list and search with no hand-maintained list (CLAUDE.md rule 5). The audit
// record is written server-side.
export function useArchiveClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<{ id: number }>('/api/clients/archive', { id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}
import { useState } from 'react';
import { isValidEmail } from './email';
import { useCreateClient } from './clients';

// Add-a-client form. useState holds only what the user is currently typing; on submit it validates
// the email, and only a proper address POSTs and invalidates the ['clients'] key. A blank or
// malformed email surfaces client-form-email-error and never creates a row. A well-formed email that
// is already in use is rejected by the server (ClientsPostLogic): the mutation errors and the same
// client-form-email-error is shown, so no duplicate row is added.
export function ClientForm() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState<string | null>(null);
  const create = useCreateClient();

  return (
    <form
      data-testid="client-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (!isValidEmail(email)) {
          setEmailError('Enter a valid email address.');
          return;
        }
        setEmailError(null);
        create.mutate(
          { name, email },
          {
            onSuccess: () => {
              setName('');
              setEmail('');
            },
            onError: () => setEmailError('That email is already in use.'),
          },
        );
      }}
    >
      <input
        data-testid="client-form-name"
        placeholder="Name"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <input
        data-testid="client-form-email"
        placeholder="Email"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          if (emailError) {
            setEmailError(null);
          }
        }}
      />
      {emailError && (
        <span data-testid="client-form-email-error" role="alert">
          {emailError}
        </span>
      )}
      <button data-testid="client-form-submit" type="submit">
        Add client
      </button>
    </form>
  );
}
import { ClientRow } from '../../slots/defs/clientRow';
import type { Client } from './clients';
import { useArchiveClient } from './clients';

// "Archive this client" — a self-contained row action filling the client-row region. Archiving tucks
// the client away rather than deleting it: nothing is lost, it just drops off the list and search.
// Clicking archives it through the shared mutation, which invalidates ['clients'] so every view
// re-reads from the server and the row drops with no hand-maintained list. The server keeps the row
// and records the archiving to the audit file.
function ArchiveClient({ client }: { client: Client }) {
  const archive = useArchiveClient();
  return (
    <button
      type="button"
      data-testid={`client-archive-${client.id}`}
      disabled={archive.isPending}
      onClick={() => archive.mutate(client.id)}
    >
      Archive
    </button>
  );
}

export const contribution = ClientRow.fill({ order: 20, Component: ArchiveClient });
import { defineSlot } from '../Slot';
import type { Client } from '../../features/clients/clients';

/**
 * The actions cell of one client row in the clients list — per-row controls that act on a single
 * client (archiving it, and more over time). The clients table renders this region once per row and
 * never lists what fills it; each action is its own `*.slot.tsx` file under `features/clients/`.
 * Handed the whole client as context, so an action has its id and name to work with.
 */
export const ClientRow = defineSlot<{ client: Client }>('client.row');

